            Definition("melonds_network_mode", "Networking Mode", "network", Type.ENUM, "string", listOf("disabled", "indirect", "direct"), mapOf("disabled" to "disabled", "indirect" to "Indirect", "direct" to "Direct"), null, null, "indirect", emptyList(), null, "none", "Configures how melonDS DS emulates Nintendo WFC. If unsure, use Indirect mode.\n\nIndirect: Use libslirp to emulate the DS's network stack. Simple and needs no setup.\nDirect: Routes emulated Wi-Fi packets to the host's network interface. Faster and more reliable, but requires an ethernet connection and that libpcap is installed. If unavailable, falls back to Indirect mode.\n\nChanges take effect at next restart. Not related to local multiplayer.", true, false, true, "core-nds-melonds_network_mode"),
            Definition("melonds_show_cursor", "Cursor Mode", "screen", Type.ENUM, "string", listOf("disabled", "touching", "timeout", "always"), mapOf("disabled" to "Never", "touching" to "While Touching", "timeout" to "Until Timeout", "always" to "Always"), null, null, "timeout", emptyList(), null, "none", "Determines when a cursor should appear on the bottom screen. Never is recommended for touch screens; the other settings are best suited for mouse or joystick input.", true, true, false, "core-nds-melonds_show_cursor"),
            Definition("melonds_cursor_timeout", "Cursor Timeout", "screen", Type.ENUM, "string", listOf("1", "2", "3", "5", "10", "15", "20", "30", "60"), mapOf("1" to "1 second", "2" to "2 seconds", "3" to "3 seconds", "5" to "5 seconds", "10" to "10 seconds", "15" to "15 seconds", "20" to "20 seconds", "30" to "30 seconds", "60" to "60 seconds"), null, null, "3", emptyList(), null, "none", "If Cursor Mode is set to \"Until Timeout\", then the cursor will be hidden if it hasn't been moved for a certain time.", true, false, true, "core-nds-melonds_cursor_timeout"),
            Definition("melonds_touch_mode", "Touch Mode", "screen", Type.ENUM, "string", listOf("joystick", "touch", "auto"), mapOf("joystick" to "Joystick", "touch" to "Pointer", "auto" to "Auto"), null, null, "auto", emptyList(), null, "none", "Determines how the console's touch screen is emulated.\n\nJoystick: Use a joystick to control the cursor. Recommended if you don't have a mouse or a real touch screen available.\nPointer: Use your mouse or touch screen to control the cursor.\nAuto: Use either Joystick or Pointer, depending on which you last touched.\n\nIf unsure, set to Auto.", true, true, false, "core-nds-melonds_touch_mode"),
            Definition("melonds_joystick_cursor_deadzone", "Joystick Cursor Deadzone", "screen", Type.ENUM, "string", listOf("0", "5", "10", "15", "20", "25", "30", "35"), mapOf("0" to "0%", "5" to "5%", "10" to "10%", "15" to "15%", "20" to "20%", "25" to "25%", "30" to "30%", "35" to "35%"), null, null, "5", emptyList(), null, "none", "If the joystick is within this deadzone the cursor will not move.", true, false, true, "core-nds-melonds_joystick_cursor_deadzone"),
