            Definition("melonds_threaded_renderer", "Threaded Software Renderer", "video", Type.ENUM, "string", listOf("disabled", "enabled"), mapOf("disabled" to "disabled", "enabled" to "enabled"), null, null, "enabled", emptyList(), null, "none", "If enabled, the software renderer will run on a separate thread. Changes take effect immediately. If unsure, leave this enabled.", true, true, false, "core-nds-melonds_threaded_renderer"),
            Definition("melonds_show_unsupported_features", "Warn About Unsupported Features", "osd", Type.ENUM, "string", listOf("enabled", "disabled"), mapOf("enabled" to "enabled", "disabled" to "disabled"), null, null, "enabled", emptyList(), null, "none", "Enable to display an on-screen message if melonDS tries to use certain unsupported features. These warnings will be logged regardless of this setting.", true, false, true, "core-nds-melonds_show_unsupported_features"),
            Definition("melonds_show_bios_warnings", "Warn About Certain BIOS Problems", "osd", Type.ENUM, "string", listOf("enabled", "disabled"), mapOf("enabled" to "enabled", "disabled" to "disabled"), null, null, "enabled", emptyList(), null, "none", "Enable to display warnings if your BIOS files have certain known problems. A warning will always be shown if your BIOS files are missing or invalid, regardless of this setting.", true, false, true, "core-nds-melonds_show_bios_warnings"),
