    val pinnedCoreOptions: Map<String, List<String>> = mapOf(
        "gba" to emptyList(),
        "nds" to listOf("melonds_render_mode", "melonds_threaded_renderer", "melonds_touch_mode", "melonds_show_cursor", "melonds_number_of_screen_layouts", "melonds_screen_layout1"),
